private static int writeRawVarint32(OutputStream out, int value) throws IOException {
    int bytesWritten = 0;
    while (true) {
        if ((value & ~0x7F) == 0) {
            out.write(value);
            bytesWritten++;
            return bytesWritten;
        } else {
            out.write((value & 0x7F) | 0x80);
            bytesWritten++;
            value >>>= 7;
        }
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
