}

private static <T> void outputFixedSizeDelimited(Schema<T> schema, T message, int size, OutputStream out, LinkedBuffer buffer, BufferRecycler recycler) throws IOException {
    final byte[] bufferArray = buffer.array;
    int offset = buffer.offset;
    int initialOffset = offset;

    // Ensure there is enough buffer space to encode the size
    int varintSize = computeRawVarint32Size(size);
    if (offset + size + varintSize < bufferArray.length) {
        // Write size
        offset = writeVarintBytes(bufferArray, offset, size);

        // Write data
        schema.writeTo(bufferArray, offset, message, buffer);
        offset += size;

        // Write bytes to output
        out.write(bufferArray, initialOffset, offset - initialOffset);
        buffer.offset = offset;
    } else {
        // Not enough space in buffer, write size to output
        writeVarint32(out, size);

        // Write data
        schema.writeTo(out, message, buffer);
    }

    recycler.recycle(buffer);
}

private static int computeRawVarint32Size(int value) {
    if ((value & (0xffffffff <<  7)) == 0) return 1;
    if ((value & (0xffffffff << 14)) == 0) return 2;
    if ((value & (0xffffffff << 21)) == 0) return 3;
    if ((value & (0xffffffff << 28)) == 0) return 4;
    return 5;
}

private static int writeVarintBytes(byte[] buffer, int offset, int value) {
    while (true) {
        if ((value & ~0x7F) == 0) {
            buffer[offset++] = (byte) value;
            return offset;
        } else {
            buffer[offset++] = (byte) ((value & 0x7F) | 0x80);
            value >>>= 7;
        }
    }
}

public static <T>int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new NullPointerException("Output, message, schema, and buffer must not be null");
    }
    try {
        // Get the size of the message
        final int size = schema.getSerializedSize(message, buffer);

        // Write the size as a varint to the output stream
        final byte[] header = new byte[10]; // Varint length for size is at most 10 bytes
        int pos = 0;
        int value = size;
        while ((value & ~0x7F) != 0) {
            header[pos++] = (byte) ((value & 0x7F) | 0x80);
            value >>>= 7;
        }
        header[pos++] = (byte) value;
        out.write(header, 0, pos);

        // Write the actual message
        schema.writeTo(out, message, buffer);

        // Return the total size written, including the header
        return size + pos;
    } catch (IOException e) {
        throw new IOException("Error writing message to output stream", e);
    }
}

