private static Type resolveTypeVariable(Class<?> targetType, TypeVariable<?> typeVariable) {
    Type genericSuperclass = targetType.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        TypeVariable<?>[] typeParameters = targetType.getSuperclass().getTypeParameters();
        for (int i = 0; i < typeParameters.length; i++) {
            if (typeParameters[i].equals(typeVariable)) {
                Type resolvedType = parameterizedType.getActualTypeArguments()[i];
                if (resolvedType instanceof Class) {
                    return resolvedType;
                } else if (resolvedType instanceof TypeVariable) {
                    return resolveTypeVariable(targetType.getSuperclass(), (TypeVariable<?>) resolvedType);
                } else {
                    return null;
                }
            }
        }
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = paramType.getActualTypeArguments();

    if (actualTypeArguments.length == 0) {
        return null;
    }

    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

    if (typeVariables.length != actualTypeArguments.length) {
        return null;
    }

    List<Class<?>> resolvedClasses = new ArrayList<>();
    for (Type arg : actualTypeArguments) {
        if (arg instanceof Class) {
            resolvedClasses.add((Class<?>) arg);
        } else {
            return null; // If there's a type variable or wildcard, we can't resolve it to a concrete class
        }
    }

    return resolvedClasses.toArray(new Class<?>[0]);
}

