static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Validate month and day range
        if (month < 1 || month > 12 || day < 1 || day > 31) {
            throw new IllegalArgumentException("Invalid timeBucket format or value");
        }

        // Calculate the base day of the month
        int baseDay = (day - 1) / dayStep * dayStep + 1;

        // Ensure the base day does not exceed the number of days in the month
        if ((month == 4 || month == 6 || month == 9 || month == 11) && baseDay > 30) {
            baseDay = 30;
        } else if (month == 2) {
            // Simplified leap year check
            boolean isLeapYear = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0));
            if ((isLeapYear && baseDay > 29) || (!isLeapYear && baseDay > 28)) {
                baseDay = isLeapYear ? 29 : 28;
            }
        }

        return year * 10000 + month * 100 + baseDay;
    } catch (Exception e) {
        throw new RuntimeException("Error compressing time bucket", e);
    }
}

