public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("The character sequence must not be null.");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length specified.");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else if (ch >= 0xD800 && ch < 0xE000) {
            // Handle surrogate pairs
            if (i + 1 < index + len && Character.isSurrogatePair(ch, str.charAt(i + 1))) {
                size += 4; // Surrogate pairs take 4 bytes in UTF-8
                i++; // Skip the next char as it's part of the surrogate pair
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair encountered.");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index is out of bounds: " + index);
    }
    if (len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Length is out of bounds: " + len);
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isSurrogate(ch)) {
            // Handle surrogate pairs
            if (i + 1 < index + len && Character.isSurrogatePair(ch, str.charAt(i + 1))) {
                size += 4;
                i++; // Skip the second surrogate character
            } else {
                throw new IllegalArgumentException("Malformed surrogate pair at index: " + i);
            }
        } else {
            size += 3;
        }
    }
    return size;
}

