    }

    final int strLength = str.length();
    int utf8Length = 0;

    // Calculate the length of the UTF-8 encoding
    for (int i = 0; i < strLength; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            utf8Length++;
        } else if (ch <= 0x7FF) {
            utf8Length += 2;
        } else if (Character.isHighSurrogate(ch)) {
            i++; // High surrogate
            if (i < strLength && Character.isLowSurrogate(str.charAt(i))) {
                utf8Length += 4; // Valid surrogate pair
            } else {
