            }
        } else {
            utf8Length += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = 0;
    int bufferCapacity = buffer.buffer.length - buffer.start;

    for (int i = 0; i < strLength; i++) {
        char ch = str.charAt(i);

        if (offset + 4 > bufferCapacity) { // Ensure enough space for the worst case (4 bytes)
            buffer = buffer.next = session.next(buffer, (bufferCapacity << 1) + utf8Length);
            buffer.start = 0;
            bufferCapacity = buffer.buffer.length;
            offset = 0;
        }

        if (ch <= 0x7F) {
            buffer.buffer[buffer.start + offset++] = (byte) ch;
        } else if (ch <= 0x7FF) {
            buffer.buffer[buffer.start + offset++] = (byte) (0xC0 | (ch >> 6));
            buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (ch & 0x3F));
        } else if (Character.isHighSurrogate(ch)) {
            i++; // High surrogate
            if (i < strLength && Character.isLowSurrogate(str.charAt(i))) {
                char lowSurrogate = str.charAt(i);
                int codePoint = Character.toCodePoint(ch, lowSurrogate);
                buffer.buffer[buffer.start + offset++] = (byte) (0xF0 | (codePoint >> 18));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (codePoint & 0x3F));
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            buffer.buffer[buffer.start + offset++] = (byte) (0xE0 | (ch >> 12));
            buffer.buffer[buffer.start + offset++] = (byte) (0x80 | ((ch >> 6) & 0x3F));
            buffer.buffer[buffer.start + offset++] = (byte) (0x80 | (ch & 0x3F));
        }
    }

