            } else {
                utf8Bytes[size++] = (byte) (0xE0 | (c >>> 12));
                utf8Bytes[size++] = (byte) (0x80 | ((c >>> 6) & 0x3F));
                utf8Bytes[size++] = (byte) (0x80 | (c & 0x3F));
            }
        }

