private static LinkedBuffer writeBytes(final byte[] bytes, final int offset, final int length, final LinkedBuffer lb) {
    int left = lb.limit - lb.offset;
    int i = offset;
    int size = length;

    while (size > 0) {
        if (left == 0) {
            lb = lb.next = newBuffer(null);
            left = lb.limit - lb.offset;
        }
        int copyLen = Math.min(left, size);
        System.arraycopy(bytes, i, lb.buffer, lb.offset, copyLen);
        lb.offset += copyLen;
        i += copyLen;
        size -= copyLen;
        left -= copyLen;
    }
    return lb;
}

