public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    byte b;
    do {
        if (shift >= 64) {
            throw new IOException("Varint too long");
        }
        b = readRawByte();
        result |= (long)(b & 0x7F) << shift;
        shift += 7;
    } while ((b & 0x80) != 0);
    return result;
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (shift < 64) {
        int b = readRawByte();
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Invalid Varint encountered");
}

