private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') {
            // It's a method descriptor, find the argument types
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: Missing ')'");
            }
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char type = argumentTypes.charAt(index);
                switch (type) {
                    case 'B': case 'C': case 'I': case 'S': case 'Z':
                        // These types each occupy one slot
                        index++;
                        break;
                    case 'F':
                        // Float also occupies one slot
                        index++;
                        break;
                    case 'J': case 'D':
                        // Long and double occupy two slots
                        index += 2;
                        break;
                    case 'L': case '[':
                        // Object and array types occupy one slot
                        while (index < argumentTypes.length() && argumentTypes.charAt(index) != ';') {
                            index++;
                        }
                        index++; // Move past the ';'
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + type);
                }
            }
        } else {
            // It's a field descriptor, pop based on the type
            switch (descriptor.charAt(0)) {
                case 'B': case 'C': case 'I': case 'S': case 'Z':
                    // These types each occupy one slot
                    break;
                case 'F':
                    // Float also occupies one slot
                    break;
                case 'J': case 'D':
                    // Long and double occupy two slots
                    break;
                case 'L': case '[':
                    // Object and array types occupy one slot
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    try {
        // Check if the descriptor is a method descriptor
        if (descriptor.startsWith("(") && descriptor.contains(")")) {
            // Extract the argument types from the descriptor
            String argTypes = descriptor.substring(1, descriptor.indexOf(')'));
            int index = 0;
            while (index < argTypes.length()) {
                char typeChar = argTypes.charAt(index);
                switch (typeChar) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        // These types take up one slot
                        index++;
                        break;
                    case 'D': case 'J':
                        // These types take up two slots
                        index += 2;
                        break;
                    case 'L':
                        // Object types are represented by L<classname>;
                        int endIndex = argTypes.indexOf(';', index);
                        if (endIndex == -1) {
                            throw new IllegalArgumentException("Invalid class descriptor");
                        }
                        index = endIndex + 1;
                        break;
                    case '[':
                        // Array types start with [
                        index++;
                        // Skip over the array dimensions and the component type
                        while (index < argTypes.length() && argTypes.charAt(index) == '[') {
                            index++;
                        }
                        if (index < argTypes.length()) {
                            char componentType = argTypes.charAt(index);
                            if (componentType == 'L') {
                                int endIndex = argTypes.indexOf(';', index);
                                if (endIndex == -1) {
                                    throw new IllegalArgumentException("Invalid class descriptor");
                                }
                                index = endIndex + 1;
                            } else {
                                index++;
                            }
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid descriptor character: " + typeChar);
                }
            }
        } else {
            // Single type descriptor
            switch (descriptor.charAt(0)) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                case 'D': case 'J':
                    break; // These are valid single type descriptors
                case 'L':
                    if (!descriptor.endsWith(";")) {
                        throw new IllegalArgumentException("Invalid object descriptor");
                    }
                    break; // Valid object descriptor
                case '[':
                    // Validate array descriptor
                    int index = 1;
                    while (index < descriptor.length() && descriptor.charAt(index) == '[') {
                        index++;
                    }
                    if (index == descriptor.length()) {
                        throw new IllegalArgumentException("Invalid array descriptor");
                    }
                    char componentType = descriptor.charAt(index);
                    if (componentType == 'L') {
                        if (!descriptor.endsWith(";")) {
                            throw new IllegalArgumentException("Invalid class descriptor");
                        }
                    } else if (!"BCFSZIDJ".contains(String.valueOf(componentType))) {
                        throw new IllegalArgumentException("Invalid descriptor character: " + componentType);
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

