public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("The box cannot be null");
    }

    float xMin = box.getMinX();
    float xMax = box.getMaxX();
    float yMin = box.getMinY();
    float yMax = box.getMaxY();

    if (xMax <= xMin) {
        throw new IllegalArgumentException("The box is not valid: xMax should be greater than xMin");
    }

    float midX = xMin + (xMax - xMin) / 2.0f;

    Box2D leftBox = new Box2D(xMin, yMin, midX, yMax);
    Box2D rightBox = new Box2D(midX, yMin, xMax, yMax);

    return new Pair<>(leftBox, rightBox);
}

