public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char currentChar = str.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 >= length) {
                throw new Exception("Invalid escape sequence at the end of string.");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
            i++; // Skip the next character as it has been processed as part of the escape sequence
        } else {
            sb.append(currentChar);
        }
    }
    return sb.toString();
}

