    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);

    try {
        for (E edge : pathEdges) {
            V targetVertex = graph.getEdgeTarget(edge);
            pathVertices.add(targetVertex);
            startVertex = targetVertex;
        }
    } catch (NullPointerException e) {
        throw new IllegalArgumentException("Tour contains edges not in the graph", e);
    }

    return new DirectedGraphPath<>(graph, pathVertices.get(0), pathVertices.get(pathVertices.size() - 1), pathEdges, 0);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edges.get(0));
    List<V> vertices = new ArrayList<>();
    vertices.add(startVertex);

    try {
        for (E edge : edges) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (vertices.get(vertices.size() - 1).equals(source)) {
                vertices.add(target);
            } else if (vertices.get(vertices.size() - 1).equals(target)) {
                vertices.add(source);
            } else {
                throw new IllegalArgumentException("Edges do not form a continuous path");
            }
        }
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Tour is not a valid path in the graph", e);
    }

    double weight = edges.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, startVertex, vertices, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> pathEdges = new ArrayList<>(tour);
    if (pathEdges.isEmpty()) {
        throw new IllegalArgumentException("Tour must contain at least one edge");
    }

    List<V> pathVertices = new ArrayList<>();
    Map<V, Integer> vertexDegree = new HashMap<>();

    // Calculate the degree of each vertex
    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertexDegree.put(source, vertexDegree.getOrDefault(source, 0) + 1);
        vertexDegree.put(target, vertexDegree.getOrDefault(target, 0) + 1);
    }

    // Find the starting vertex (a vertex with an odd degree)
    V startVertex = null;
    for (Map.Entry<V, Integer> entry : vertexDegree.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }

    // If no vertex with an odd degree is found, pick any vertex
    if (startVertex == null) {
        startVertex = pathEdges.get(0).getSource();
    }

    try {
        pathVertices.add(startVertex);
        while (!pathEdges.isEmpty()) {
            E nextEdge = null;
            V currentVertex = pathVertices.get(pathVertices.size() - 1);
            for (E edge : pathEdges) {
                V source = graph.getEdgeSource(edge);
                V target = graph.getEdgeTarget(edge);
                if (source.equals(currentVertex) || target.equals(currentVertex)) {
                    nextEdge = edge;
                    break;
                }
            }
            if (nextEdge == null) {
                throw new IllegalStateException("No valid path can be formed");
            }
            pathEdges.remove(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
            pathVertices.add(nextVertex);
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid tour provided", e);
    }

    return new GraphPathImpl<>(graph, pathVertices.get(0), pathVertices.get(pathVertices.size() - 1), pathVertices, pathEdges, (double) pathEdges.size());
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0.0, new ArrayList<>());
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V currentVertex = null;
    Map<V, List<E>> vertexToEdges = new HashMap<>();

    // Group edges by their source vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        vertexToEdges.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex
    for (Map.Entry<V, List<E>> entry : vertexToEdges.entrySet()) {
        if (entry.getValue().size() == 1) {
            startVertex = entry.getKey();
            break;
        }
    }

    // If no start vertex found, arbitrarily choose one
    if (startVertex == null) {
        startVertex = vertexToEdges.keySet().iterator().next();
    }

    List<E> pathEdges = new ArrayList<>();
    currentVertex = startVertex;

    // Construct the path
    while (!tour.isEmpty()) {
        List<E> edges = vertexToEdges.get(currentVertex);
        if (edges == null || edges.isEmpty()) {
            break;
        }

        E nextEdge = edges.get(0);
        pathEdges.add(nextEdge);
        tour.remove(nextEdge);

        // Remove the edge from the map
        V nextVertex = graph.getEdgeTarget(nextEdge);
        vertexToEdges.get(currentVertex).remove(nextEdge);
        if (vertexToEdges.get(currentVertex).isEmpty()) {
            vertexToEdges.remove(currentVertex);
        }

        currentVertex = nextVertex;
    }

    double weight = pathEdges.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, startVertex, weight, pathEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Set<E> visitedEdges = new HashSet<>();
    V currentVertex = startVertex;

    while (!visitedEdges.containsAll(tour)) {
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex))) {
                visitedEdges.add(edge);
                currentVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                vertexList.add(currentVertex);
                break;
            }
        }
    }

    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

