        }
        Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
        if (sourceBucket == null || sourceBucket.isEmpty()) {
            return; // No need to move vertices if the source bucket is empty
        }

        Set<Integer> targetBucket = bucketsByLabel.get(0);
        if (targetBucket == null) {
            throw new IllegalArgumentException("Bucket with label 0 does not exist.");
        }

        for (Integer vertex : sourceBucket) {
            labels.set(vertex, 0); // Update the label of the vertex to 0
            targetBucket.add(vertex); // Move the vertex to the bucket with label 0
        }

        sourceBucket.clear(); // Clear the bucket with the original minLabel
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid index access in labels list.", e);
    }
}

