public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null.");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Stack to simulate the path traversal
    Stack<String> pathStack = new Stack<>();
    for (String part : pathParts) {
        if (!part.isEmpty()) {
            pathStack.push(part);
        }
    }

    for (String part : relativePathParts) {
        if (part.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop();
            }
        } else if (!part.isEmpty() && !part.equals(".")) {
            pathStack.push(part);
        }
    }

    // Reconstruct the path
    StringBuilder resultPath = new StringBuilder();
    for (String part : pathStack) {
        if (resultPath.length() > 0) {
            resultPath.append("/");
        }
        resultPath.append(part);
    }

    // Ensure the path is absolute (starts with a '/')
    if (!path.isEmpty() && path.charAt(0) == '/' && resultPath.length() > 0 && resultPath.charAt(0) != '/') {
        resultPath.insert(0, '/');
    }

    return resultPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must not be null");
    }

    // Normalize the paths by ensuring they use "/" as separators
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Use a list to build the final path
    List<String> resultPath = new ArrayList<>(Arrays.asList(pathComponents));

    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!resultPath.isEmpty() && !resultPath.get(resultPath.size() - 1).isEmpty()) {
                resultPath.remove(resultPath.size() - 1);
            }
        } else if (!component.equals(".")) {
            resultPath.add(component);
        }
    }

    // Join the components back into a single string
    return String.join("/", resultPath);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths by replacing backslashes with forward slashes
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    // Use a stack to build the final path
    Stack<String> pathStack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!pathStack.isEmpty()) {
                    pathStack.pop();
                }
            } else {
                pathStack.push(component);
            }
        }
    }

    for (String component : relativeComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            if (component.equals("..")) {
                if (!pathStack.isEmpty()) {
                    pathStack.pop();
                }
            } else {
                pathStack.push(component);
            }
        }
    }

    // Build the final path
    StringBuilder finalPath = new StringBuilder();
    while (!pathStack.isEmpty()) {
        finalPath.insert(0, pathStack.pop());
        if (!pathStack.isEmpty()) {
            finalPath.insert(0, "/");
        }
    }

    return finalPath.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must not be null");
    }

    try {
        java.nio.file.Path basePath = java.nio.file.Paths.get(path);
        java.nio.file.Path finalPath = basePath.resolve(relativePath).normalize();
        return finalPath.toString();
    } catch (Exception e) {
        throw new RuntimeException("Error applying relative path", e);
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must not be null");
    }

    // Normalize the paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    int pathIndex = pathComponents.length - 1;
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--; // Move up one directory, but not above root
            }
        } else if (!component.equals(".")) {
            // Add the component to the path
            pathComponents[++pathIndex] = component;
        }
    }

    // Build the final path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathComponents[i]);
    }

    return result.toString();
}

