public int readTag() throws IOException {
    // Attempt to read the next byte which represents the tag
    int firstByte = input.read();

    // If the first byte is -1, it indicates EOF (End of File)
    if (firstByte == -1) {
        return 0;
    }

    // Check if the tag is a single byte (most common case)
    if ((firstByte & 0x80) == 0) {
        return firstByte;
    }

    // Handle multi-byte tags
    int tag = firstByte & 0x7F;
    int shift = 7;

    while (true) {
        firstByte = input.read();
        if (firstByte == -1) {
            throw new IOException("Unexpected EOF while reading tag");
        }

        tag |= (firstByte & 0x7F) << shift;
        if ((firstByte & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed tag: too long");
        }
    }

    return tag;
}

